#ifndef MESH_CUBED_SPHERE_HERMITE_BOUNDARY_PROBE_HPP_
#define MESH_CUBED_SPHERE_HERMITE_BOUNDARY_PROBE_HPP_
#include "mesh/cubed_sphere/ray_collar_probe.hpp"
namespace cubed_sphere {
// Diagnostic C2 boundary jet atlas. Global Cartesian stored components are
// arbitrary 3D functions. Native physical-r normal jets G,H come from the
// original radial fit; only F|Sigma,G,H are globally interpolated. Interior
// values never contaminate the angular interpolation of a prescribed trace.
class HermiteBoundaryProbe {
 public:
 using Jets=CenteredSurfaceAtlas::Jets;
 const CompositeDifference &g;const ScriSurface &surface;const std::vector<Real>&volume,&boundary;int fields;
 SurfaceMLSProbe angular;std::vector<Real> normal_first,normal_second;
 mutable std::map<std::array<Real,3>,SurfaceMLSProbe::Row> cache;
 Real radial_condition=0;mutable Real maximum_condition=0,maximum_l1=0,maximum_reproduction=0;
 HermiteBoundaryProbe(const ScriSurface&s,const std::vector<Real>&v,const std::vector<Real>&b,int f):g(s.grid),surface(s),volume(v),boundary(b),fields(f),angular(g.mesh,1),normal_first(b.size()),normal_second(b.size()){
  if(v.size()!=size_t(g.count*f)||b.size()!=s.rows.size()*f)throw std::invalid_argument("Hermite boundary layout");const int nodes=s.radial_nodes,n=g.n;Real radial[8],dr[8],ddr[8];std::vector<Real> scaled;for(int r=0;r<nodes;++r){radial[r]=r==nodes-1?1:Real(n-(nodes-1)+r+.5)/n;Jet basis(1);for(int k=0;k<nodes;++k)if(k!=r){Real other=k==nodes-1?1:Real(n-(nodes-1)+k+.5)/n;basis=basis*(Jet::Variable(1,0)-Jet(other))/Jet(radial[r]-other);}dr[r]=basis.d[0];ddr[r]=basis.h[0][0];scaled.push_back((radial[r]-1)/(1-radial[0]));}const Real span=1-radial[0];for(int k=0;k<nodes;++k){Real first=0,second=0;for(int r=0;r<nodes-1;++r){const Real v=k?std::pow((radial[r]-1)/span,k):0;first+=span*dr[r]*v;second+=span*span*ddr[r]*v;}maximum_reproduction=std::max({maximum_reproduction,std::abs(first-(k==1?1.:0)),std::abs(second-(k==2?2.:0))});}if(maximum_reproduction>1e-10)throw std::runtime_error("Hermite normal polynomial reproduction guard");radial_condition=RayCollarProbe::VandermondeCondition(scaled);if(!(radial_condition<1e8))throw std::runtime_error("Hermite radial condition guard");
  for(size_t p=0;p<s.rows.size();++p){const auto &row=s.rows[p];const Real q[3]={1,(row.j+.5)/n,(row.k+.5)/n};const auto slope=RadialSlope(row.block,q);if(!(slope.f>0))throw std::runtime_error("Hermite radial map orientation");for(int r=0;r<nodes-1;++r){Real point[3]={radial[r],q[1],q[2]},x[3];g.mesh.Forward(row.block,point,x);Real radius=0;for(Real a:x)radius+=a*a;radius=std::sqrt(radius);if(std::abs(radius-(g.mesh.radii.back()+(radial[r]-1)*slope.f))>1e-12*g.mesh.radii.back())throw std::runtime_error("Hermite requires affine physical-r radial map; rss term unavailable");}
   for(int f=0;f<fields;++f){const Real anchor=b[p*fields+f];Real first=0,second=0;for(int r=0;r<nodes-1;++r){const Real difference=v[f*g.count+g.Index(row.block,n-(nodes-1)+r,row.j,row.k)]-anchor;first+=dr[r]*difference;second+=ddr[r]*difference;}normal_first[p*fields+f]=first/slope.f;normal_second[p*fields+f]=second/(slope.f*slope.f);}}
 }
 Jet RadialSlope(int block,const Real*q)const{const auto &b=g.mesh.blocks[block];if(b.face<0||b.layer!=int(g.mesh.radii.size())-1||std::abs(b.hi[0]-1)>1e-14)throw std::runtime_error("Hermite boundary block map");const Real ds=b.hi[0]-b.lo[0];if(b.layer>0)return Jet(ds*(g.mesh.radii[b.layer]-g.mesh.radii[b.layer-1]));const Jet u=Jet(b.lo[1])+Jet(b.hi[1]-b.lo[1])*Jet::Variable(q[1],1),v=Jet(b.lo[2])+Jet(b.hi[2]-b.lo[2])*Jet::Variable(q[2],2);return Jet(ds)*(Jet(g.mesh.radii[0])-Jet(g.mesh.half_width)*Power(Jet(1)+u*u+v*v,.5));}
 const SurfaceMLSProbe::Row&Weights(int block,const Real*q)const{std::array<Real,3> key{Real(block),q[1],q[2]};for(int a=1;a<3;++a){Real lattice=std::round(2*g.n*q[a]);if(std::abs(2*g.n*q[a]-lattice)<1e-12)key[a]=lattice/(2*g.n);}auto found=cache.find(key);if(found==cache.end()){Real point[3]={1,q[1],q[2]},x[3];g.mesh.Forward(block,point,x);found=cache.emplace(key,angular.Build(x)).first;maximum_l1=std::max(maximum_l1,found->second.l1);maximum_reproduction=std::max(maximum_reproduction,found->second.reproduction);maximum_condition=std::max(maximum_condition,found->second.condition*radial_condition);if(maximum_condition>=1e8)throw std::runtime_error("Hermite angular/radial factor-condition guard");}return found->second;}
 std::vector<Real> Sample(int block,const Real*q)const{const auto &row=Weights(block,q);std::vector<Real> out(3*fields);for(int which=0;which<3;++which){const auto &data=which==0?boundary:(which==1?normal_first:normal_second);for(int f=0;f<fields;++f){const Real anchor=data[row.ids[0]*fields+f];out[which*fields+f]=anchor;for(size_t i=0;i<row.ids.size();++i)out[which*fields+f]+=row.weights[i]*(data[row.ids[i]*fields+f]-anchor);}}return out;}
 Jets At(int block,const Real*q)const{if(q[0]!=1)throw std::invalid_argument("Hermite probe exact boundary only");const Real h=1./g.n,w[5]={1./12,-2./3,0,2./3,-1./12},w2[5]={-1./12,4./3,-2.5,4./3,-1./12};std::vector<Real> sample[5][5];for(int j=0;j<5;++j)for(int k=0;k<5;++k){const Real p[3]={1,q[1]+(j-2)*h,q[2]+(k-2)*h};sample[j][k]=Sample(block,p);}const auto geometry=g.mesh.Geometry(block,q);const auto slope=RadialSlope(block,q);Jets out;out.value.resize(fields);out.d.resize(fields);out.dd.resize(fields);for(int f=0;f<fields;++f){const Real anchor=sample[2][2][f],G=sample[2][2][fields+f],H=sample[2][2][2*fields+f];out.value[f]=anchor;Real dq[3]={slope.f*G,0,0},ddq[3][3]{};ddq[0][0]=slope.f*slope.f*H; // current affine map: rss=0
   Real dG[3]{};for(int j=0;j<5;++j){dq[1]+=w[j]*(sample[j][2][f]-anchor)/h;dq[2]+=w[j]*(sample[2][j][f]-anchor)/h;dG[1]+=w[j]*(sample[j][2][fields+f]-G)/h;dG[2]+=w[j]*(sample[2][j][fields+f]-G)/h;ddq[1][1]+=w2[j]*(sample[j][2][f]-anchor)/(h*h);ddq[2][2]+=w2[j]*(sample[2][j][f]-anchor)/(h*h);for(int k=0;k<5;++k)ddq[1][2]+=w[j]*w[k]*(sample[j][k][f]-anchor)/(h*h);}for(int A=1;A<3;++A)ddq[0][A]=ddq[A][0]=slope.f*dG[A]+slope.d[A]*G;ddq[2][1]=ddq[1][2];for(int i=0;i<3;++i)for(int A=0;A<3;++A){out.d[f][i]+=geometry.J[A][i]*dq[A];for(int j=0;j<3;++j){out.dd[f][i][j]+=geometry.H[A][i][j]*dq[A];for(int B=0;B<3;++B)out.dd[f][i][j]+=geometry.J[A][i]*geometry.J[B][j]*ddq[A][B];}}}return out;
 }
};
} // namespace cubed_sphere
#endif
